import { useEffect, useMemo, useRef, useState, type ComponentRef, type ReactNode } from 'react'
import { Platform, Pressable, ScrollView, Text, TextInput, View, type StyleProp, type ViewStyle } from 'react-native'
import Animated, { FadeIn, FadeInDown } from 'react-native-reanimated'
import * as Haptics from 'expo-haptics'
import { ArrowRight, ChevronRight, CornerDownLeft, Mic, Search, Sparkles } from 'lucide-react-native'
import { errorMessages } from '@ondai/core'
import { hairlineWidth, typeStyle, useMotion, useTheme } from '@ondai/tokens/react'
import { IonBorder } from '../ion-border/ion-border'
import { KeyHint } from '../key-hint/key-hint'
import { OnDeviceBadge } from '../on-device-badge/on-device-badge'
import { Sheet } from '../sheet/sheet'
import { StreamingText } from '../streaming-text/streaming-text'
import { ThinkingIndicator } from '../thinking-indicator/thinking-indicator'
import { ToolConfirmCard } from '../tool-confirm-card/tool-confirm-card'
import type { CommandAction } from './actions'
import { registerToolNames, useCommandBar, type CommandResult, type UseCommandBarOptions } from './use-command-bar'

export interface CommandBarProps extends UseCommandBarOptions {
  presentation?: 'spotlight' | 'sheet' | 'inline' | 'pill' | 'fullscreen'
  variant?: 'glass' | 'solid' | 'minimal'
  size?: 'sm' | 'md' | 'lg'
  open?: boolean
  onOpenChange?: (open: boolean) => void
  placeholder?: string
  showVoice?: boolean
  showKeyHints?: boolean
  showBadge?: boolean
  /** Recently run action ids shown when the query is empty. */
  recent?: string[]
  /** Group suggestions by `actions` / `screens` / `items`. */
  grouped?: boolean
  /** Called when the mic is pressed; return transcribed text. */
  onVoice?: () => Promise<string>
  /** Pre-filled query (playground / deep links). */
  initialQuery?: string
  /** Submit the initial query on mount. */
  autoRun?: boolean
  /** Focus the input when the bar opens (default true; turn off for embedded demos). */
  autoFocus?: boolean
  /** Render inside the current view instead of a Modal (web previews). */
  inline?: boolean
  renderIcon?: (action: CommandAction<any>) => ReactNode
  style?: StyleProp<ViewStyle>
  testID?: string
}

/**
 * "Spotlight for your app": natural language becomes one of the app's registered actions,
 * chosen by on-device tool calling, with a preview and confirmation for risky actions.
 */
export function CommandBar({
  presentation = 'spotlight',
  variant = 'glass',
  size = 'md',
  open: openProp,
  onOpenChange,
  placeholder = 'Ask or do anything…',
  showVoice = true,
  showKeyHints = Platform.OS === 'web',
  showBadge = true,
  recent,
  grouped = true,
  onVoice,
  initialQuery = '',
  autoRun = false,
  autoFocus = true,
  inline,
  renderIcon,
  style,
  testID,
  ...hookOptions
}: CommandBarProps) {
  const t = useTheme()
  const motion = useMotion()
  const bar = useCommandBar(hookOptions)
  const [openState, setOpenState] = useState(openProp ?? (presentation === 'inline' || presentation === 'pill'))
  const open = openProp ?? openState
  const setOpen = (v: boolean) => {
    setOpenState(v)
    onOpenChange?.(v)
  }
  const inputRef = useRef<ComponentRef<typeof TextInput>>(null)
  const busy = bar.status === 'thinking' || bar.status === 'streaming' || bar.status === 'tool'

  useEffect(() => registerToolNames(hookOptions.actions), [hookOptions.actions])
  useEffect(() => {
    if (initialQuery) bar.setQuery(initialQuery)
    if (autoRun && initialQuery) void bar.submit(initialQuery).catch(() => {})
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialQuery, autoRun])
  useEffect(() => {
    // On web the DOM input takes `preventScroll`; native ignores the argument.
    if (open && autoFocus && presentation !== 'pill') setTimeout(() => (inputRef.current as unknown as { focus: (o?: { preventScroll: boolean }) => void } | null)?.focus({ preventScroll: true }), 60)
  }, [open, autoFocus, presentation])
  useEffect(() => {
    if (bar.status === 'done') void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch(() => {})
  }, [bar.status])

  const submit = () => {
    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light).catch(() => {})
    void bar.submit().catch(() => {})
  }
  const pick = (a: CommandAction<any>) => {
    void Haptics.selectionAsync().catch(() => {})
    void bar.runAction(a, {}).catch(() => {})
  }

  const groups = useMemo(() => {
    const list = bar.query.trim() ? bar.suggestions : recent?.length ? recent.map((id) => hookOptions.actions.find((a) => a.id === id)).filter((a): a is CommandAction<any> => !!a) : bar.suggestions
    if (!grouped) return [{ key: 'all', title: bar.query.trim() ? 'Suggestions' : recent?.length ? 'Recent' : 'Suggestions', items: list }]
    const order: Array<CommandAction<any>['group']> = ['actions', 'screens', 'items']
    return order.map((g) => ({ key: g!, title: g!, items: list.filter((a) => (a.group ?? 'actions') === g) })).filter((g) => g.items.length)
  }, [bar.query, bar.suggestions, recent, hookOptions.actions, grouped])

  const surfaceColor = variant === 'solid' ? t.colors.surface : variant === 'minimal' ? 'transparent' : t.colors.glassFill
  const inputHeight = size === 'sm' ? 44 : size === 'md' ? 52 : 60
  const sizeKey = size === 'sm' ? 'md' : size === 'md' ? 'lg' : 'xl'

  const field = (
    <IonBorder active={busy} focused={open} radius="lg" fill={surfaceColor} glow={busy && variant !== 'minimal'} width={1.5}>
      <View style={{ flexDirection: 'row', alignItems: 'center', height: inputHeight, paddingLeft: 14, paddingRight: 8, gap: 10 }}>
        {busy ? <ThinkingIndicator variant="dots" size="sm" /> : <Search size={18} strokeWidth={1.5} color={t.colors.textTertiary} />}
        <TextInput
          ref={inputRef}
          testID={testID ? `${testID}-input` : undefined}
          value={bar.query}
          onChangeText={bar.setQuery}
          onSubmitEditing={submit}
          onKeyPress={(e) => {
            if (e.nativeEvent.key === 'Escape') setOpen(false)
          }}
          placeholder={placeholder}
          placeholderTextColor={t.colors.textTertiary}
          selectionColor={t.colors.accent.solid}
          returnKeyType="go"
          autoCorrect={false}
          accessibilityLabel="Command input"
          style={[typeStyle(t, sizeKey), { flex: 1, color: t.colors.text, paddingVertical: 0, outlineStyle: 'none' } as never]}
        />
        {showVoice && onVoice ? (
          <Pressable
            accessibilityRole="button"
            accessibilityLabel="Speak"
            onPress={() => void onVoice().then((text) => (text ? bar.submit(text) : null)).catch(() => {})}
            hitSlop={8}
            style={{ width: 36, height: 36, borderRadius: 18, alignItems: 'center', justifyContent: 'center' }}
          >
            <Mic size={18} strokeWidth={1.5} color={t.colors.textSecondary} />
          </Pressable>
        ) : null}
        {showKeyHints ? <KeyHint keys={bar.query ? ['enter'] : ['cmd', 'K']} size="sm" /> : null}
      </View>
    </IonBorder>
  )

  const rows = (
    <View style={{ gap: 4, paddingTop: 8 }}>
      {bar.error ? (
        <Animated.View entering={motion.enabled ? FadeIn.duration(160) : undefined} style={{ paddingHorizontal: 12, paddingVertical: 10, borderRadius: t.radii.md, borderWidth: hairlineWidth, borderColor: t.colors.danger, gap: 6 }}>
          <Text style={[typeStyle(t, 'sm'), { color: t.colors.text }]}>{bar.error.message || errorMessages.unknown}</Text>
          <Pressable onPress={submit} accessibilityRole="button" style={{ minHeight: 28, justifyContent: 'center' }}>
            <Text style={[typeStyle(t, 'sm', { weight: 'medium' }), { color: t.colors.textSecondary }]}>Try again</Text>
          </Pressable>
        </Animated.View>
      ) : null}
      {bar.pendingConfirmation ? <ToolConfirmCard pending={bar.pendingConfirmation} presentation="banner" /> : null}
      {bar.result ? <ResultRow result={bar.result} /> : null}
      {bar.text && !bar.result ? <StreamingText text={bar.text} streaming={bar.status === 'streaming'} size="sm" color={t.colors.textSecondary} /> : null}
      {!bar.result && !bar.pendingConfirmation
        ? groups.map((g) => (
            <View key={g.key} style={{ gap: 2 }}>
              <Text style={[typeStyle(t, 'xs', { mono: true, tag: true, weight: 'medium' }), { color: t.colors.textTertiary, paddingHorizontal: 12, paddingVertical: 6 }]}>{g.title}</Text>
              {g.items.map((a) => (
                <Pressable
                  key={a.id}
                  onPress={() => pick(a)}
                  accessibilityRole="button"
                  style={({ pressed }) => ({ flexDirection: 'row', alignItems: 'center', gap: 12, minHeight: 44, paddingHorizontal: 12, borderRadius: t.radii.md, backgroundColor: pressed ? t.colors.elevatedHover : 'transparent' })}
                >
                  <View style={{ width: 28, height: 28, borderRadius: 8, backgroundColor: t.colors.input, alignItems: 'center', justifyContent: 'center' }}>
                    {renderIcon?.(a) ?? <Sparkles size={14} strokeWidth={1.5} color={t.colors.textSecondary} />}
                  </View>
                  <View style={{ flex: 1 }}>
                    <Text style={[typeStyle(t, 'md'), { color: t.colors.text }]} numberOfLines={1}>
                      {a.title}
                    </Text>
                    {a.description ? (
                      <Text style={[typeStyle(t, 'sm'), { color: t.colors.textTertiary }]} numberOfLines={1}>
                        {a.description}
                      </Text>
                    ) : null}
                  </View>
                  <ChevronRight size={16} strokeWidth={1.5} color={t.colors.textTertiary} />
                </Pressable>
              ))}
            </View>
          ))
        : null}
      <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: 12, paddingTop: 10, paddingBottom: 4 }}>
        {showBadge ? <OnDeviceBadge size="sm" state={bar.status} provider={bar.provider} locality={bar.locality as never} /> : <View />}
        {showKeyHints ? (
          <View style={{ flexDirection: 'row', gap: 10, alignItems: 'center' }}>
            <KeyHint keys={['enter']} size="sm" variant="plain" />
            <Text style={[typeStyle(t, 'xs', { mono: true }), { color: t.colors.textTertiary }]}>run</Text>
            <KeyHint keys={['esc']} size="sm" variant="plain" />
            <Text style={[typeStyle(t, 'xs', { mono: true }), { color: t.colors.textTertiary }]}>close</Text>
          </View>
        ) : null}
      </View>
    </View>
  )

  const panel = (
    <View style={{ padding: 10, gap: 4 }}>
      {field}
      <ScrollView keyboardShouldPersistTaps="handled" style={{ maxHeight: 360 }}>
        {rows}
      </ScrollView>
    </View>
  )

  if (presentation === 'inline') {
    return (
      <View style={[{ gap: 4 }, style]} testID={testID}>
        {field}
        {(bar.query || bar.result || bar.pendingConfirmation || bar.error) ? rows : null}
      </View>
    )
  }
  if (presentation === 'pill') {
    return (
      <View style={[{ gap: 8 }, style]} testID={testID}>
        {open ? (
          <Animated.View entering={motion.enabled ? FadeInDown.duration(200) : undefined} style={{ borderRadius: t.radii.xl, backgroundColor: surfaceColor, borderWidth: hairlineWidth, borderColor: t.colors.hairline }}>
            {panel}
          </Animated.View>
        ) : null}
        <Pressable
          onPress={() => setOpen(!open)}
          accessibilityRole="button"
          accessibilityLabel={open ? 'Close command bar' : 'Open command bar'}
          style={{ alignSelf: 'center', flexDirection: 'row', alignItems: 'center', gap: 8, height: 44, paddingHorizontal: 18, borderRadius: t.radii.pill, backgroundColor: t.colors.text }}
        >
          <Sparkles size={16} strokeWidth={1.5} color={t.colors.bg} />
          <Text style={[typeStyle(t, 'md', { weight: 'medium' }), { color: t.colors.bg }]}>{open ? 'Close' : 'Ask'}</Text>
        </Pressable>
      </View>
    )
  }
  return (
    <Sheet open={open} onClose={() => setOpen(false)} presentation={presentation === 'sheet' ? 'sheet' : presentation === 'fullscreen' ? 'fullscreen' : 'spotlight'} variant={variant === 'solid' ? 'solid' : 'glass'} inline={inline} style={style} testID={testID}>
      {panel}
    </Sheet>
  )
}

function ResultRow({ result }: { result: CommandResult }) {
  const t = useTheme()
  const motion = useMotion()
  const text = result.preview ?? (typeof result.result === 'string' ? result.result : result.action.title)
  return (
    <Animated.View entering={motion.enabled ? FadeInDown.duration(220) : undefined} style={{ flexDirection: 'row', alignItems: 'center', gap: 12, paddingHorizontal: 12, paddingVertical: 10, borderRadius: t.radii.md, backgroundColor: t.colors.accent.soft }}>
      <View style={{ width: 28, height: 28, borderRadius: 8, backgroundColor: t.colors.accent.solid, alignItems: 'center', justifyContent: 'center' }}>
        <ArrowRight size={14} strokeWidth={2} color={t.colors.onAccent} />
      </View>
      <View style={{ flex: 1 }}>
        <Text style={[typeStyle(t, 'md', { weight: 'medium' }), { color: t.colors.text }]} numberOfLines={1}>
          {result.action.title}
        </Text>
        <Text style={[typeStyle(t, 'sm'), { color: t.colors.textSecondary }]} numberOfLines={2}>
          {text}
        </Text>
      </View>
      <CornerDownLeft size={14} strokeWidth={1.5} color={t.colors.textTertiary} />
    </Animated.View>
  )
}

export default CommandBar

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { tool, type ToolSet } from '@ondai/core'
import { z } from 'zod'
import { matchEnum, normalizeText, similarity, useLocalModel, useOndai, useStructured, useToolAgent, type PendingConfirmation, type ToolMeta, type ToolStep } from '@ondai/core'
import type { AiState } from '@ondai/tokens'
import type { CommandAction } from './actions'
import { commandInstructions } from './prompts'
import { actionChoiceSchema } from './schema'

export interface UseCommandBarOptions {
  actions: Array<CommandAction<any>>
  /** Extra guidance for the model (app name, domain words). */
  instructions?: string
  /** How many tools are sent to the model (the rest are preselected by relevance). */
  maxTools?: number
  /** Suggestions shown before the model runs. */
  maxSuggestions?: number
  /** Called after an action ran. */
  onRun?: (action: CommandAction<any>, params: Record<string, unknown>, result: unknown) => void
  component?: string
}

export interface CommandResult {
  action: CommandAction<any>
  params: Record<string, unknown>
  preview?: string
  result?: unknown
  /** Which rung of the ladder produced it. */
  via: 'tools' | 'structured' | 'keyword'
}

export interface CommandBarState {
  query: string
  setQuery: (q: string) => void
  suggestions: Array<CommandAction<any>>
  submit: (q?: string) => Promise<CommandResult | null>
  runAction: (action: CommandAction<any>, params?: Record<string, unknown>) => Promise<CommandResult>
  status: AiState
  result: CommandResult | null
  text: string
  error: Error | null
  pendingConfirmation: PendingConfirmation | null
  confirm: (edited?: Record<string, unknown>) => void
  cancel: () => void
  steps: ToolStep[]
  reset: () => void
  /** Which rung the device supports: tools → structured → keyword. */
  mode: 'tools' | 'structured' | 'keyword'
  provider?: string
  locality?: string
}

/** Score actions against a query with keywords and fuzzy similarity. Deterministic, instant. */
export function rankActions(actions: Array<CommandAction<any>>, query: string, limit = 6): Array<CommandAction<any>> {
  const q = normalizeText(query)
  if (!q) return actions.slice(0, limit)
  const scored = actions.map((a) => {
    const hay = normalizeText([a.title, a.description ?? '', ...(a.keywords ?? [])].join(' '))
    const tokens = q.split(' ')
    let overlap = 0
    for (const tk of tokens) if (hay.split(' ').some((h) => h === tk || (tk.length > 2 && h.startsWith(tk)))) overlap++
    const score = (overlap / tokens.length) * 0.7 + similarity(q, normalizeText(a.title)) * 0.3
    return { a, score }
  })
  return scored
    .filter((s) => s.score > 0.15)
    .sort((x, y) => y.score - x.score)
    .slice(0, limit)
    .map((s) => s.a)
}

/** Natural-language → one registered action. Tool calling when available, structured enum otherwise, keyword search always. */
export function useCommandBar(options: UseCommandBarOptions): CommandBarState {
  const { actions, instructions, maxTools = 5, maxSuggestions = 6, onRun, component = 'command-bar' } = options
  const [query, setQuery] = useState('')
  const [result, setResult] = useState<CommandResult | null>(null)
  const ondai = useOndai()
  const toolsModel = useLocalModel('tools')
  const structuredModel = useLocalModel('structured')
  const mode: CommandBarState['mode'] = toolsModel.isReady ? 'tools' : structuredModel.isReady ? 'structured' : 'keyword'
  const byId = useMemo(() => new Map(actions.map((a) => [a.id, a])), [actions])
  const onRunRef = useRef(onRun)
  onRunRef.current = onRun

  const runAction = useCallback(
    async (action: CommandAction<any>, params: Record<string, unknown> = {}, via: CommandResult['via'] = 'keyword') => {
      const out = await action.run(params)
      const r: CommandResult = { action, params, preview: action.preview?.(params), result: out, via }
      setResult(r)
      onRunRef.current?.(action, params, out)
      return r
    },
    [],
  )

  // Tools rung: one AI SDK tool per action; risky actions ask first.
  const tools = useMemo<ToolSet>(() => {
    const set: ToolSet = {}
    for (const a of actions) {
      set[toolName(a.id)] = tool({
        description: [a.title, a.description, a.keywords?.length ? `Keywords: ${a.keywords.join(', ')}` : ''].filter(Boolean).join('. '),
        inputSchema: a.params ?? z.object({}),
        execute: async (input) => {
          const r = await runAction(a, input as Record<string, unknown>, 'tools')
          return r.preview ?? r.result ?? 'done'
        },
      })
    }
    return set
  }, [actions, runAction])
  const meta = useMemo<Record<string, ToolMeta>>(() => Object.fromEntries(actions.map((a) => [toolName(a.id), { title: a.title, risk: a.risk ?? 'low', policy: a.risk === 'high' ? 'ask' : 'auto' }])), [actions])
  const agent = useToolAgent({ tools, meta, instructions: [commandInstructions(true), instructions].filter(Boolean).join(' '), maxTools, maxSteps: 2, component })

  // Structured rung.
  const ids = actions.map((a) => a.id) as [string, ...string[]]
  const structured = useStructured({
    schema: actionChoiceSchema(ids.length ? ids : ['none']),
    instructions: [commandInstructions(false), `Action ids: ${actions.map((a) => `${a.id} (${a.title})`).join('; ')}.`, instructions].filter(Boolean).join(' '),
    component,
    refine: (obj) => {
      const m = matchEnum(obj.action, ids)
      return m ? { object: { ...obj, action: m.value }, confidence: m.score } : obj
    },
  })

  const submit = useCallback(
    async (q?: string) => {
      const text = (q ?? query).trim()
      if (!text) return null
      setResult(null)
      // Resolve the rung now (hook state may not have settled on first render).
      const toolsReady = (await ondai.availability('tools')).status === 'ready'
      const structuredReady = !toolsReady && (await ondai.availability('structured')).status === 'ready'
      const rung: CommandBarState['mode'] = toolsReady ? 'tools' : structuredReady ? 'structured' : 'keyword'
      if (rung === 'tools') {
        const r = await agent.run(text)
        const call = r.toolCalls[0]
        if (call) {
          const a = byId.get(fromToolName(call.toolName))
          if (a) {
            const res: CommandResult = { action: a, params: (call.input as Record<string, unknown>) ?? {}, preview: a.preview?.(call.input as never), result: r.toolResults[0]?.output, via: 'tools' }
            setResult(res)
            return res
          }
        }
        // Model found nothing: fall through to keyword.
      } else if (rung === 'structured') {
        const obj = await structured.run(text)
        const a = byId.get(obj.action)
        if (a) {
          const params = a.params ? paramsFromArgument(a.params, obj.argument) : {}
          return runAction(a, params, 'structured')
        }
      }
      const best = rankActions(actions, text, 1)[0]
      if (!best) return null
      const params = best.params ? paramsFromArgument(best.params, text) : {}
      return runAction(best, params, 'keyword')
    },
    [query, ondai, agent, structured, byId, actions, runAction],
  )

  const suggestions = useMemo(() => rankActions(actions, query, maxSuggestions), [actions, query, maxSuggestions])
  const status: AiState = mode === 'tools' ? agent.status : mode === 'structured' ? structured.status : 'idle'
  const error = mode === 'tools' ? agent.error : mode === 'structured' ? structured.error : null

  useEffect(() => {
    if (toolsModel.isReady && toolsModel.provider) void toolsModel.prewarm()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [toolsModel.isReady])

  return {
    query,
    setQuery,
    suggestions,
    submit,
    runAction: (a, p) => runAction(a, p, 'keyword'),
    status,
    result,
    text: agent.text,
    error,
    pendingConfirmation: agent.pendingConfirmation,
    confirm: agent.confirm,
    cancel: agent.cancel,
    steps: agent.steps,
    reset: () => {
      setQuery('')
      setResult(null)
      agent.reset()
      structured.reset()
    },
    mode,
    provider: toolsModel.provider ?? structuredModel.provider,
    locality: toolsModel.locality ?? structuredModel.locality,
  }
}

/** Tool names must be identifiers; action ids may contain ':' or '/'. */
export function toolName(id: string): string {
  return id.replace(/[^a-zA-Z0-9_]/g, '_')
}
const reverse = new Map<string, string>()
function fromToolName(name: string): string {
  return reverse.get(name) ?? name
}
export function registerToolNames(actions: Array<CommandAction<any>>) {
  for (const a of actions) reverse.set(toolName(a.id), a.id)
}

/** Without tool calling, fill the first string param with the argument text. */
function paramsFromArgument(schema: z.ZodObject<z.ZodRawShape>, argument: string): Record<string, unknown> {
  const out: Record<string, unknown> = {}
  for (const [k, f] of Object.entries(schema.shape)) {
    const def = (f as { def?: { type?: string } }).def
    const inner = (def as { innerType?: { def?: { type?: string } } } | undefined)?.innerType?.def?.type
    if (def?.type === 'string' || (def?.type === 'optional' && inner === 'string')) {
      out[k] = argument
      break
    }
  }
  return out
}

import { z } from 'zod'
import type { ToolRisk } from '@ondai/core'

export interface CommandAction<P extends z.ZodObject<z.ZodRawShape> = z.ZodObject<z.ZodRawShape>> {
  id: string
  title: string
  description?: string
  /** Extra words users might type. */
  keywords?: string[]
  /** `actions` (do something), `screens` (navigate), `items` (open a record). */
  group?: 'actions' | 'screens' | 'items'
  /** Lucide icon name or any React node is resolved by the component. */
  icon?: string
  risk?: ToolRisk
  /** Parameters the model should extract. Keep them flat with enums. */
  params?: P
  run: (params: z.infer<P>) => void | Promise<unknown> | string
  /** Optional preview text shown before running (e.g. "Create task · Buy milk · tomorrow"). */
  preview?: (params: z.infer<P>) => string
}

/** Typed helper that keeps `run` parameters inferred from `params`. */
export function defineAction<P extends z.ZodObject<z.ZodRawShape>>(action: CommandAction<P>): CommandAction<P> {
  return action
}

export function defineActions(actions: Array<CommandAction<any>>): Array<CommandAction<any>> {
  const ids = new Set<string>()
  for (const a of actions) {
    if (ids.has(a.id)) throw new Error(`[ondai] duplicate action id "${a.id}"`)
    ids.add(a.id)
  }
  return actions
}

/** Turn expo-router style routes into navigation actions. */
export function routesToActions(routes: Array<{ href: string; title: string; keywords?: string[] }>, navigate: (href: string) => void): Array<CommandAction<any>> {
  return routes.map((r) => ({ id: `route:${r.href}`, title: r.title, keywords: r.keywords, group: 'screens', risk: 'low', run: () => navigate(r.href) }))
}

export const emptyParams = z.object({})

import { z } from 'zod'

/** Fallback for providers without tool calling: structured choice of an action id plus the free-text argument. */
export const actionChoiceSchema = (ids: [string, ...string[]]) =>
  z.object({
    action: z.enum(ids),
    /** The remainder of the request the action needs (title, query, etc.). */
    argument: z.string(),
  })
